import asyncio
from async_bridge import run_sync, with_timeout


def run_with_deadline(coros: list, seconds: float) -> list:
    """Run coroutines concurrently from synchronous code, returning their results in input order.
    Any coroutine not finished within `seconds` is cancelled and its result is None.
    Can be called repeatedly in the same process."""
    async def _run_all_with_deadline(coros, seconds):
        tasks = [asyncio.create_task(c) for c in coros]
        results = []
        for task in tasks:
            try:
                res = await asyncio.wait_for(task, timeout=seconds)
                results.append(res)
            except asyncio.TimeoutError:
                task.cancel()
                try:
                    await task
                except asyncio.CancelledError:
                    pass
                results.append(None)
        return results

    return run_sync(_run_all_with_deadline(coros, seconds))

from web_utils import parse_content_type, content_charset


def describe_upload(content_type: str, data: bytes) -> dict:
    """Given a Content-Type header and initial bytes of the body, return a dict with keys:
    - 'mime': lower-cased media type without parameters
    - 'charset': lower-cased charset parameter or None if not present
    - 'image': one of 'png', 'jpeg', 'gif' or None, detected from data's signature bytes
    """
    mime, params = parse_content_type(content_type)
    charset = params.get("charset")
    if charset is not None:
        charset = charset.lower()
    else:
        charset = None

    # Detect image type from signature bytes
    image = None
    if data.startswith(b"\x89PNG\r\n\x1a\n"):
        image = "png"
    elif data.startswith(b"\xff\xd8\xff"):
        image = "jpeg"
    elif data.startswith(b"GIF87a") or data.startswith(b"GIF89a"):
        image = "gif"
    else:
        # Not requested but bmp and webp detection could be here if needed
        image = None

    return {"mime": mime, "charset": charset, "image": image}

